exercise.answer:
const colors = ["赤", "青", "黄", "緑"];
// 添字は 0 から始まるので、最初の要素は colors[0] です
console.log(colors[0]);
// 最後の添字は「要素数 - 1」。length を使えば要素が増えても動きます
console.log(colors[colors.length - 1]);
console.log(colors.length);
